function createInvoice(data: any) {
  if (!data) data = {};
  if (!Array.isArray(data.items)) data.items = [];
  const id = typeof data.id === 'string' ? data.id : String(Date.now());
  return { id, items: data.items };
}

type User = { id: string; email: string; active?: boolean };
function activateUser(u: any) {
  if (typeof u !== 'object' || typeof u.id !== 'string') throw new Error('invalid user');
  if (typeof u.email !== 'string') u.email = '';
  u.active = true;
  saveUser(u as User);
}

